/** Product presentation only. All metrics/states come from existing evidence. */
import {qualifyingEvidence} from './model.js';
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state=v=>`<span class="trace-status ${esc(v)}">${esc(v)}</span>`;
const metric=(title,value,note)=>`<article class="panel summary"><h3>${esc(title)}</h3><strong class="summary-value">${esc(value)}</strong><p class="muted">${esc(note)}</p></article>`;
const identity=r=>JSON.stringify([r.kind,r.document_kind,r.instance,r.scope,r.identifier,r.version]);
const short=r=>`${r.document_kind||r.kind.replaceAll('_',' ')} ${r.kind==='COMMIT'?r.identifier.slice(0,12)+'…':r.identifier}${r.version?' @ '+r.version:''}`;
export function reviewSummary(review){
 if(!review)return null;const prs=review.provenance.pull_requests;
 return {numerator:prs.filter(pr=>qualifyingEvidence(pr).units.length>0).length,denominator:prs.length,status:review.provenance.status};
}
export function renderSystemOverview(report,verification){
 const reviews=reviewSummary(report.review_evidence),trace=report.traceability_evidence?.result.metrics.find(m=>m.dimension==='work_item_implementation');
 const cards=[metric('Components',report.components.length,'Directory-based software scope'),metric('High / critical concentration',report.components.filter(c=>['HIGH','CRITICAL'].includes(c.risk)).length,'Historical activity concentration; not employee performance'),metric('PRs with qualifying review',reviews?.denominator?`${reviews.numerator} / ${reviews.denominator}`:'Unavailable',reviews?`${reviews.status} selected merged-PR collection; components may overlap`:'No review evidence in this report'),metric('Work items with implementation paths',trace?.value!==null&&trace?`${trace.numerator} / ${trace.denominator}`:'Unavailable',trace?`${trace.status} · ${trace.collection_status}`:'No implementation traceability in this report')];
 const labels={requirement_implementation:'Requirements with implementation paths',requirement_tests:'Requirements with declared test links',requirement_architecture:'Requirements with architecture links',executed_tests:'Tests with qualified execution observations'};
 for(const [dimension,title] of Object.entries(labels)){const m=verification?.metrics.find(m=>m.dimension===dimension);cards.push(metric(title,m&&m.value!==null?`${m.numerator} / ${m.denominator}`:'Unavailable',m?`${m.status} · ${m.collection_status} · unknown ${m.unknown_count} / excluded ${m.excluded_count}`:'No requirement/test evidence attached to this report'));}
 const gaps=verification?.gaps.length,codeGaps=report.traceability_evidence?.result.gaps.length;
 return `<article class="panel summary journey"><h2>What does the evidence say about this system?</h2><p>Start with component concentration, follow implementation connections, then inspect review and test observations.</p><p class="muted">Missing evidence does not mean missing engineering work. Connection evidence and historical PASS do not establish correctness or handover readiness.</p><ol><li>Continuity: where is historical evidence concentrated?</li><li>Traceability: which explicit implementation and test connections can be inspected?</li><li>Reviews &amp; Verification: what interactions and exact-target observations were declared?</li></ol></article>${cards.join('')}<article class="panel summary"><h3>Evidence gaps</h3><p>${codeGaps===undefined?'Implementation gaps unavailable.':`${codeGaps} recorded code gaps.`} ${gaps===undefined?'Requirement gaps unavailable.':`${gaps} recorded requirement gaps.`}</p><p class="muted">Open Traceability for scope, status and supporting evidence. Unavailable is not a measured zero.</p></article>`;
}
export function renderRequirements(report,verification){
 if(!verification)return '<div class="empty"><h3>Requirement and test evidence unavailable</h3><p>No requirement evidence is attached to this report. Absence does not mean no requirements or tests exist.</p><p>The Synthetic Product Demo includes explicit requirement, architecture and test examples. Current report imports support Git, reviews and work-item traceability; portable requirement import remains a later increment.</p></div>';
 const same=(a,b)=>identity(a)===identity(b),links=verification.associations;
 return `<h2>Requirements → implementation → tests</h2><p><span class="tag">SYNTHETIC</span> Declared links for this fictional system. Open an evidence inspector for exact source identities, versions and target qualification.</p>${verification.requirements.map(q=>{
 const tests=links.filter(a=>a.relation==='TEST_REQUIREMENT'&&same(a.target,q.reference)).map(a=>a.source),docs=links.filter(a=>a.relation==='DOCUMENT_REQUIREMENT'&&same(a.target,q.reference)).map(a=>a.source),paths=verification.paths.filter(p=>same(p.association.source,q.reference));
 return `<details class="trace-card"><summary>${esc(short(q.reference))} · implementation ${state(q.implementation)} · declared tests ${state(q.tests)} · architecture ${state(q.architecture)}</summary><h3>Implementation connections</h3>${paths.map(p=>`<p class="story-chain">${[q.reference,...p.code_path.nodes].map(n=>`<span>${esc(short(n))}</span>`).join('<span aria-hidden="true"> → </span>')} ${state(p.code_path.status)}</p>`).join('')||'<p>No qualified code path observed. Inspect the gap status; this does not prove missing implementation.</p>'}<h3>Architecture links</h3><p>${docs.map(d=>esc(short(d))).join(' · ')||'No declared architecture link.'}</p><h3>Declared test links and separate observations</h3>${tests.map(t=>{const runs=verification.runs.filter(r=>same(r.test,t));return `<p>${esc(short(t))} → ${runs.map(r=>`${state(r.outcome)} · ${r.qualified?'qualified exact version/target':'excluded: '+esc(r.reason)}`).join('; ')||'No declared execution observation.'}</p>`;}).join('')||'<p>No declared test link.</p>'}${renderPathReviews(report,paths)}<p class="muted">PASS is only a historical declared observation for its exact test version and target; it does not prove requirement correctness, sufficient coverage or acceptance readiness.</p></details>`;
 }).join('')}`;
}
function renderPathReviews(report,paths){
 const review=report.review_evidence;if(!review)return '<p>PR review context unavailable.</p>';
 const p=review.provenance.provenance,refs=paths.flatMap(path=>path.code_path.nodes).filter(n=>n.kind==='PULL_REQUEST'&&n.provider===p.provider&&n.repository===p.repository),ids=[...new Set(refs.map(r=>r.identifier))];
 const prs=ids.map(id=>review.provenance.pull_requests.find(pr=>pr.identifier===id)).filter(Boolean);
 return `<h3>Review context on explicit PR paths</h3>${prs.map(pr=>`<p>PR ${esc(pr.identifier)} · qualifying historical interaction: ${qualifyingEvidence(pr).units.map(esc).join(', ')||'none observed'}</p>`).join('')||'<p>No matching PR review boundary available.</p>'}<p class="muted">Review context follows the existing PR reference, not a new requirement-review link. Review coverage does not measure review quality.</p>`;
}
export function renderObservations(verification){
 if(!verification)return '<p class="empty">Test observations unavailable for this report. This does not mean no tests ran. Open the Synthetic Product Demo to inspect declared examples.</p>';
 return `<h2>Historical test observations</h2><p><span class="tag">SYNTHETIC</span> Separate from PR reviews; no tests execute here.</p><div class="risk-grid">${Object.entries(verification.outcomes).map(([k,n])=>`<div><span>${esc(k)}</span><strong>${n}</strong></div>`).join('')}</div>${verification.runs.map(r=>`<details class="trace-card"><summary>${esc(short(r.test))} · ${state(r.outcome)} · ${r.qualified?'qualified exact version/target':'excluded'}</summary><p>Observation ${esc(short(r.reference))} · ${esc(r.observed_at)} · ${esc(r.reason||'Exact declared test version and target')}</p><p>Snapshot ${esc(r.target.alias)} · revision ${esc(r.target.revision)} · fingerprint ${esc(r.target.fingerprint)} · boundary ${esc(r.boundary)}</p></details>`).join('')}<p class="muted">PASS/FAIL establish a qualified historical execution observation; SKIPPED/UNKNOWN do not count as executed tests. PASS is only a historical declared observation for that exact test version and target snapshot. It does not establish requirement correctness, sufficient coverage or readiness.</p>`;
}
export function renderReviewInspector(review){
 if(!review)return '';
 const collection=review.provenance,identity=i=>i?`identifier ${esc(i.identifier)} · display name ${esc(i.display_name??'Not declared')} · is_bot ${esc(i.is_bot)}`:'Not declared';
 const metadata=[...Object.entries(collection.provenance),['collection_status',collection.status],['diagnostics',collection.diagnostics.join(' · ')||'none'],['closed_pull_requests_inspected',collection.closed_pull_requests_inspected??'Not declared'],['merged_pull_requests_observed',collection.merged_pull_requests_observed??'Not declared'],['component_depth',review.component_depth??'Not declared']];
 return `<details class="trace-card"><summary>Review source events and exclusions</summary><dl>${metadata.map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')}</dl>${collection.pull_requests.map(pr=>`<details><summary>PR ${esc(pr.identifier)} · author ${esc(pr.author.identifier)} · ${pr.reviews.length} events</summary><p>Author: ${identity(pr.author)}</p><p>merged_at ${esc(pr.merged_at??'Not declared')} · Paths: ${pr.changed_paths.map(esc).join(', ')}</p><ul>${pr.reviews.map(e=>`<li>${esc(e.identifier)} · ${esc(e.state)}<br>Reviewer: ${identity(e.reviewer)}<br>submitted_at ${esc(e.submitted_at??'Not declared')} · provider_order ${esc(e.provider_order??'Not declared')} · dismissed ${esc(e.dismissed)}</li>`).join('')}</ul><p>Effective exclusions: ${Object.entries(qualifyingEvidence(pr).exclusions).map(([k,n])=>`${esc(k)} ${n}`).join(' · ')||'none'}</p></details>`).join('')}</details>`;
}
